-- 🎬 Vidéos des histoires + 📚 carte « Histoires des Prophètes » (Nadia, 22/11) + 🖼️ fonds d'écran
-- Vidéos : table histoires_videos (YouTube), CACHÉES aux élèves au départ : l'enseignante choisit celles qui sont visibles.
create table if not exists public.histoires_videos (
  id uuid primary key default gen_random_uuid(),
  fiche_id uuid not null references public.petits_fiches(id) on delete cascade,
  youtube_id text not null,
  titre text,
  chaine text,
  a_revoir boolean not null default false,
  visible boolean not null default false,
  position integer not null default 0,
  created_at timestamptz not null default now()
);
create index if not exists histoires_videos_fiche on public.histoires_videos (fiche_id, position);
alter table public.histoires_videos enable row level security;
drop policy if exists "histoires_videos_lecture" on public.histoires_videos;
create policy "histoires_videos_lecture" on public.histoires_videos for select to authenticated
  using (visible or public.has_role(auth.uid(), 'admin'::app_role));
drop policy if exists "histoires_videos_admin" on public.histoires_videos;
create policy "histoires_videos_admin" on public.histoires_videos for all to authenticated
  using (public.has_role(auth.uid(), 'admin'::app_role)) with check (public.has_role(auth.uid(), 'admin'::app_role));
do $$ begin
  begin alter publication supabase_realtime add table public.histoires_videos; exception when duplicate_object then null; end;
end $$;

insert into public.reglages_appli (cle, valeur) values ('fonds_ecran', '{"actif": true, "actifs": ["jp1","jp2","jp3","jp4","jp5","jg1","jg2","jg4","jg5","np1","np2","np3","np4","np5","ng1","ng2","ng3","ng4","ng5"]}'::jsonb)
on conflict (cle) do nothing;

-- Les 4 nouvelles histoires chez les tout-petits (après les 4 existantes)

insert into public.petits_fiches (rubrique, titre, emoji, arabe, texte, position) select 'histoires', 'Adam, le premier homme', '🌱', 'رَبَّنَا ظَلَمْنَآ أَنفُسَنَا', 'Allah a créé le prophète Adam (que la paix soit sur lui), le premier homme, avec de la terre. Il lui a appris le nom de toutes choses.
Allah a demandé aux anges de se prosterner devant Adam : ils l''ont tous fait, sauf Iblis, qui était orgueilleux.
Adam et son épouse habitaient le Paradis. Allah leur avait dit de ne pas s''approcher d''un arbre. Le shaytan les a trompés, et ils en ont mangé.
Adam a regretté et a demandé pardon à Allah avec cette dou''a (écrite en arabe en haut). Allah lui a pardonné : Il est Celui qui accepte le repentir, le Très Miséricordieux.', 100 where not exists (select 1 from public.petits_fiches where rubrique='histoires' and titre='Adam, le premier homme');
insert into public.petits_fiches (rubrique, titre, emoji, arabe, texte, position) select 'histoires', 'Souleymane et la fourmi', '🐜', 'يَٰٓأَيُّهَا ٱلنَّمْلُ ٱدْخُلُوا۟ مَسَٰكِنَكُمْ', 'Allah a donné au prophète Souleymane (que la paix soit sur lui) un grand royaume, et Il lui a appris le langage des oiseaux.
Un jour, avec son armée, il est arrivé à la vallée des fourmis. Une petite fourmi a dit : « Ô fourmis, entrez dans vos maisons, pour que Souleymane et son armée ne vous écrasent pas sans s''en rendre compte. » Souleymane a souri et a remercié Allah.
Une autre fois, la huppe, un oiseau, lui a apporté la nouvelle d''une reine et de son peuple qui adoraient le soleil. Souleymane les a invités à adorer Allah seul, et la reine s''est soumise à Allah.', 110 where not exists (select 1 from public.petits_fiches where rubrique='histoires' and titre='Souleymane et la fourmi');
insert into public.petits_fiches (rubrique, titre, emoji, arabe, texte, position) select 'histoires', 'Saleh et la chamelle', '🐪', null, 'Le prophète Saleh (que la paix soit sur lui) a été envoyé au peuple de Thamoud, qui taillait des maisons dans les montagnes. Il leur disait d''adorer Allah seul.
Allah leur a envoyé un signe : une chamelle. Saleh leur a dit : « Laissez-la manger sur la terre d''Allah et ne lui faites aucun mal. » L''eau était partagée : un jour pour la chamelle, un jour pour eux.
Mais les plus méchants ont tué la chamelle. Alors Allah a puni Thamoud, et Il a sauvé Saleh et les croyants.', 120 where not exists (select 1 from public.petits_fiches where rubrique='histoires' and titre='Saleh et la chamelle');
insert into public.petits_fiches (rubrique, titre, emoji, arabe, texte, position) select 'histoires', 'L''armée de l''éléphant', '🐘', 'أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِأَصْحَٰبِ ٱلْفِيلِ', 'Il y a très longtemps, des gens sont venus à La Mecque avec un éléphant, pour détruire la Kaaba, la maison d''Allah.
Allah a envoyé des oiseaux, en groupes, qui lançaient sur eux de petites pierres. L''armée a été détruite, et la Kaaba a été protégée.
Allah le raconte dans la sourate Al-Fîl (l''éléphant).', 130 where not exists (select 1 from public.petits_fiches where rubrique='histoires' and titre='L''armée de l''éléphant');

-- La carte « Histoires des Prophètes » (les grands) reprend les mêmes histoires (copie modifiable à part)
insert into public.petits_fiches (rubrique, titre, arabe, texte, emoji, image_url, audio_url, versets, position) select 'prophetes', titre, arabe, texte, emoji, image_url, audio_url, versets, position from public.petits_fiches h where h.rubrique='histoires' and not exists (select 1 from public.petits_fiches p where p.rubrique='prophetes' and p.titre=h.titre);

