-- Copie des quiz vers les histoires des grands
insert into public.petits_quiz (fiche_id, question, audio_url, choix, position) select p.id, x.question, x.audio_url, x.choix, x.position from public.petits_quiz x join public.petits_fiches h on h.id=x.fiche_id and h.rubrique='histoires' join public.petits_fiches p on p.rubrique='prophetes' and p.titre=h.titre where not exists (select 1 from public.petits_quiz y where y.fiche_id=p.id and y.question=x.question);

